SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'kf_test_sites', 'k_f-Versuchsstandorte', 'json', NULL, false, '§5.3.3.6', 'Plan 3: Zeilen je Versuchsstandort (Verfahren nach Tab. 11, gemessener k_f); Minimum → k_f_sites_min (A138-05-D1); Anzahl/Dichte-Regel STAGED (a138-D-2, a138-F-1).', 'imported_unverified', 'Für die Berechnung wird die bemessungsrelevante Infiltrationsrate optimalerweise durch Versuche vor Ort bestimmt (Anhang A). Die Versuchsstandorte sind über den Standort der geplanten Versickerungsanlage so zu verteilen, dass unterschiedliche Untergrundverhältnisse erfasst werden. I Bei kompakten/flächenhaften Versickerungsanlagen ist mindestens ein Versuchsstandort je $150 \mathrm{~m}^{2}$ Sohlenfläche der Versickerungsanlage erforderlich. I Übersteigt die Länge der geplanten Versickerungsanlage 10 m , ist bei heterogenen Bodenverhältnissen mindestens ein weiterer Versuchsstandort vorzusehen. Bei größeren Versickerungsanlagen sind Versuchsstandorte mindestens alle 25 m der Anlagenlänge anzuordnen. Auf der sicheren Seite liegend wird die minimale Infiltrationsrate als $k_{\mathrm{f}}$-Wert verwendet.', 'register', '{"title":"k_f-Versuchsstandorte","subtitle":"§5.3.3.6 — je Standort ein Versuch; maßgebend ist der minimale Wert","add_label":"+ Standort","placement":"section","columns":[{"key":"label","label":"Standort","type":"text","required":true},{"key":"method","label":"Verfahren (Tab. 11)","type":"lookup_key","required":true,"lookup":{"table_code":"TAB11"}},{"key":"f_methode_row","label":"f_Methode","type":"lookup_value","lookup":{"table_code":"TAB11","key_column":"method","value":"f_methode"}},{"key":"depth_m","label":"Tiefe","type":"number","unit":"m","min":0},{"key":"k_f_measured","label":"k_f gemessen","type":"number","unit":"m/s","required":true,"min":0},{"key":"date","label":"Datum","type":"date"}],"footer":["k_f_sites_min"],"note":"Auf der sicheren Seite liegend wird die minimale Infiltrationsrate als $k_{\\mathrm{f}}$-Wert verwendet."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kf_test_sites') AND w.code = 'A138-05' AND s.code = 'DWA-A-138-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'soil_layers', 'Bodenschichten (geschichtetes Bodenprofil)', 'json', NULL, false, '§5.3.1', 'Plan 3: Zeilen je Bodenschicht (Tiefe, Bodenart nach Tab. 13, k_f, BBZ-Kennzeichen); Minimum → k_f_layer_min (A138-05-D3).', 'imported_unverified', 'Bei geschichteten Bodenprofilen sind maßgebliche Bodenschichten zu wählen, um die bemessungsrelevante Infiltrationsrate festzulegen. Die maßgeblichen Bodenschichten sind bei zentralen Versickerungsanlagen in einem Bodengutachten auszuweisen, bei dezentralen Versickerungsanlagen wird dies empfohlen. Bei oberirdischen Anlagen muss bei der Festlegung der bemessungsrelevanten In- filtrationsrate für die Bemessung die vorhandene oder geplante bewachsene Bodenzone berücksichtigt werden; die jeweils geringere Durchlässigkeit ist maßgebend.', 'register', '{"title":"Bodenschichten (Bodenprofil)","subtitle":"§5.3.1 — maßgebliche Bodenschichten; die jeweils geringere Durchlässigkeit ist maßgebend","add_label":"+ Schicht","placement":"section","columns":[{"key":"label","label":"Schicht","type":"text"},{"key":"top_m","label":"Oberkante","type":"number","unit":"m","min":0},{"key":"bottom_m","label":"Unterkante","type":"number","unit":"m","min":0},{"key":"bodenart","label":"Bodenart","type":"text","datalist":["Mittel-/Feinsand","schluffiger Sand, sandiger Schluff, Schluff"]},{"key":"k_f","label":"k_f","type":"number","unit":"m/s","required":true,"min":0},{"key":"is_bbz","label":"bewachsene Bodenzone","type":"boolean"}],"footer":["k_f_layer_min"],"note":"die jeweils geringere Durchlässigkeit ist maßgebend"}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'soil_layers') AND w.code = 'A138-05' AND s.code = 'DWA-A-138-1';
