SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'feasibility_code', 'Umsetzbarkeit nach Tabelle 3 als Code (1 = alle Spalte-2-Kriterien erfüllt · 2 = nicht nachgewiesen möglich · 3 = ein Spalte-4-Kriterium trifft zu)', 'number', NULL, false, '§5.1.1, Tab. 3', 'Plan 3: Ausgabe der Gleichung A138-02-D1 (Spaltenlogik der Tab. 3 über die sieben Kriterienfelder). Code 2 ist NICHT gleich Spalte 3: zwei Spalte-4-Fälle werden konstruktionsbedingt in Code 2 gefaltet — (1) Trinkwasserschutzgebiet mit nicht vernachlässigbarem Risiko (L747, kein Risikofeld; jede Zone ⇒ 2) und (2) k_f < 1·10⁻⁶ m/s ohne möglichen Anschluss/Ableitung (L748, kein Feld) — daher „nicht nachgewiesen möglich“; Ableitung von feasibility_determination STAGED (a138-D-1).', 'imported_unverified', 'Eine Versickerung von Niederschlagswasser ist grundsätzlich möglich, wenn alle der oben genannten Kriterien zutreffen und durch Fachgutachten nachgewiesen sind. Ist ein Kriterium nicht erfüllt sind die entsprechenden Kriterien nach Spalte 3 zu prüfen. & Wenn eine oder mehrere Kriterien dieser Kategorie zutreffen, sind technische und planerische Maßnahmen durch die Fachplanenden aufzuzeigen und ggf. mit der zuständigen Genehmigungsbehörde abzustimmen & Wenn eines der oben aufgeführten Kriterien zutrifft, ist eine Versickerung von Niederschlagswasser in der Regel nicht zulässig', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'feasibility_code') AND w.code = 'A138-02' AND s.code = 'DWA-A-138-1';
